import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.HashSet; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { String[] nx = br.readLine().split("\\s+"); int n = Integer.parseInt(nx[0]); int x = Integer.parseInt(nx[1]); StringTokenizer st = new StringTokenizer(br.readLine()); HashSet<Integer> set = new HashSet<>(); for (int i = 0; i < n; i++) { set.add(Integer.parseInt(st.nextToken())); } int distinctCount = set.size(); if (distinctCount == x) { System.out.println("Good"); } else if (distinctCount < x) { System.out.println("Bad"); } else { System.out.println("Average"); } } } }